const e = $input.first().json;
const miss = ['envelope_version','business_id','lead_id','trace_id'].filter(k => !e[k]);
if (miss.length) throw new Error('LEAD:' + (e.lead_id || '') + '|TRACE:' + (e.trace_id || '') + '|invalid envelope, missing: ' + miss.join(', '));
if (e.envelope_version !== '1.0') throw new Error('LEAD:' + e.lead_id + '|TRACE:' + e.trace_id + '|unsupported envelope_version ' + e.envelope_version);
return [{ json: e }];

const L = $input.first().json;
if (!L.lead_id) return []; // not in EXTRACTED state: no-op
const cfg = L.config || {};
const W = Object.assign({ base_enquiry: 15, contact_name: 10, product_interest: 20, budget_stated: 25,
  budget_fit_bonus: 15, budget_below_catalog_penalty: 40, urgency_high: 20, urgency_medium: 10, company: 10 },
  (cfg.scoring && cfg.scoring.weights) || {});
const T = Object.assign({ hot_min: 70, warm_min: 40 }, (cfg.scoring && cfg.scoring.thresholds) || {});
const pi = Array.isArray(L.product_interest) ? L.product_interest : JSON.parse(L.product_interest || '[]');
const bd = [];
const add = (label, pts) => { if (pts !== 0) bd.push({ factor: label, points: pts }); };
add('valid enquiry', W.base_enquiry);
if (L.contact_name) add('contact name provided', W.contact_name);
if (pi.length) add('specific product interest: ' + pi.join(', '), W.product_interest);
const budget = L.budget_value != null ? Number(L.budget_value) : null;
if (budget != null) {
  add('budget stated (' + budget + ' ' + (L.budget_currency || '') + ')', W.budget_stated);
  if (L.min_price != null && budget >= Number(L.min_price)) add('budget fits catalog', W.budget_fit_bonus);
  else if (L.min_price != null) add('budget below cheapest catalog item', -W.budget_below_catalog_penalty);
}
if (L.urgency === 'high') add('high urgency', W.urgency_high);
else if (L.urgency === 'medium') add('medium urgency', W.urgency_medium);
if (L.company) add('business customer: ' + L.company, W.company);
let score = Math.max(0, Math.min(100, bd.reduce((s, b) => s + b.points, 0)));
const band = score >= T.hot_min ? 'HOT' : score >= T.warm_min ? 'WARM' : 'COLD';
return [{ json: { lead_id: L.lead_id, business_id: L.business_id, trace_id: L.trace_id,
  score, band, breakdown: bd, thresholds: T,
  extraction: { contact_name: L.contact_name, company: L.company, budget_value: L.budget_value,
    budget_currency: L.budget_currency, product_interest: pi, urgency: L.urgency, location: L.location } } }];

const raw = $input.first().json;
let r = raw;
if (r && Array.isArray(r.candidates)) r = { content: (r.candidates[0] || {}).content };
if (r && r.content && Array.isArray(r.content.parts)) r = r.content.parts.map(p => p.text || '').join('');
else if (r.content !== undefined) r = r.content;
if (typeof r === 'string') { try { r = JSON.parse(r.replace(/^```json?\s*|```\s*$/g, '')); } catch (e) { r = null; } }
const q = $('Compute Rubric Score').first().json;
const reasons = (r && Array.isArray(r.reasons) && r.reasons.length) ? r.reasons
  : q.breakdown.map(b => b.factor + ' (' + (b.points > 0 ? '+' : '') + b.points + ')'); // deterministic fallback: rubric IS the reason
return [{ json: { ...q, reasons } }];

const j = $input.first().json;
const src = $('Validate Envelope').first().json;
return [{ json: { envelope_version: '1.0', business_id: src.business_id, lead_id: j.lead_id, trace_id: src.trace_id, agent: 'qualifier', status: 'ok', payload: {} } }];

const j = $input.first().json;
let out;
if (Array.isArray(j.candidates)) {
  out = { ...j, __model: 'gemini-2.5-flash', __fallback: false };
} else if (Array.isArray(j.choices)) {
  const u = j.usage || {};
  out = { candidates: [{ content: { parts: [{ text: (j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '' }] },
    finishReason: (j.choices[0] && j.choices[0].finish_reason) || null }],
    usageMetadata: { promptTokenCount: u.prompt_tokens || 0, candidatesTokenCount: u.completion_tokens || 0, thoughtsTokenCount: 0 },
    __model: 'gpt-4o-mini', __fallback: true };
} else {
  out = { candidates: [], usageMetadata: {}, __model: 'unknown', __fallback: true };
}
return [{ json: out }];
